def totales(texto_csv):
    import csv
    import io

    resultado = {}
    if not texto_csv:
        return resultado

    reader = csv.reader(io.StringIO(texto_csv))
    filas = list(reader)

    if not filas:
        return resultado

    cabecera = filas[0]
    if cabecera != ["producto", "cantidad", "precio"]:
        return resultado

    for fila in filas[1:]:
        if not fila:
            continue
        if len(fila) < 3:
            continue
        producto = fila[0]
        cantidad = fila[1]
        precio = fila[2]
        try:
            cantidad_int = int(cantidad.strip())
            precio_float = float(precio.strip())
            importe = cantidad_int * precio_float
            resultado[producto] = resultado.get(producto, 0) + importe
        except ValueError:
            continue

    return {k: round(v, 2) for k, v in resultado.items()}
