def comparar_versiones(a, b):
    partes_a = list(map(int, a.split('.')))
    partes_b = list(map(int, b.split('.')))
    max_len = max(len(partes_a), len(partes_b))
    while len(partes_a) < max_len:
        partes_a.append(0)
    while len(partes_b) < max_len:
        partes_b.append(0)
    for i in range(max_len):
        if partes_a[i] < partes_b[i]:
            return -1
        elif partes_a[i] > partes_b[i]:
            return 1
    return 0
